import React, { useState, useEffect, useMemo } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks, getTrackDetails } from '../services/api';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

const TrackSearch = ({ searchTerm, onShowSimilarTracks }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [contextMenu, setContextMenu] = useState(null);

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm)
        .then(setFilteredTracks)
        .catch((error) => {
          console.error('Error fetching tracks:', error);
        });
    }
  }, [searchTerm]);

  const columns = useMemo(() => [
    { Header: 'Track Name', accessor: 'name' },
    { Header: 'Artist Name', accessor: 'artists[0].name' },
    { Header: 'Album Name', accessor: 'album.name' },
    { Header: 'Release Date', accessor: 'album.release_date', Cell: ({ value }) => value ? value.split('-')[0] : 'Unknown' },
    { Header: 'Preview', accessor: 'id', Cell: ({ value }) => value ? (
        <iframe
          src={`https://open.spotify.com/embed/track/${value}`}
          width="100%"
          height="80"
          allow="encrypted-media"
          style={{ border: 'none' }}
        ></iframe>
      ) : 'No Preview'
    },
  ], []);

  const data = useMemo(() => filteredTracks, [filteredTracks]);
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } = useTable({ columns, data }, useSortBy);

  // Right-click handler to show custom menu
  const handleRightClick = (event, track) => {
    event.preventDefault();
    setContextMenu({
      visible: true,
      x: event.pageX,
      y: event.pageY,
      track,
    });
  };

  // Function to fetch similar tracks
  const fetchSimilarTracks = async (track) => {
    setContextMenu(null);
    try {
      const details = await getTrackDetails(track.id);
      onShowSimilarTracks(details);
    } catch (error) {
      console.error('Error fetching track details:', error);
    }
  };

  // Close context menu on click outside
  const handleClickOutside = () => {
    setContextMenu(null);
  };

  useEffect(() => {
    document.addEventListener('click', handleClickOutside);
    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, []);

  return (
    <div>
      {filteredTracks.length > 0 ? (
        <table {...getTableProps()} style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }} className="results-table">
          <thead>
            {headerGroups.map(headerGroup => (
              <tr {...headerGroup.getHeaderGroupProps()} style={{ backgroundColor: '#00b4db', color: 'white' }}>
                {headerGroup.headers.map(column => (
                  <th {...column.getHeaderProps(column.getSortByToggleProps())} style={{ padding: '10px', borderBottom: '1px solid #ddd' }}>
                    {column.render('Header')}
                    {column.isSorted ? (column.isSortedDesc ? <ArrowDownwardIcon /> : <ArrowUpwardIcon />) : null}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody {...getTableBodyProps()}>
            {rows.map((row, index) => {
              prepareRow(row);
              return (
                <tr
                  {...row.getRowProps()}
                  onContextMenu={(e) => handleRightClick(e, row.original)} // Right-click event to open menu
                  style={{
                    backgroundColor: index % 2 === 0 ? '#f9f9f9' : 'white', // Alternating row colors
                    color: '#606060',
                    fontFamily: 'Arial, sans-serif',
                    borderBottom: '1px solid #ddd',
                    cursor: 'context-menu' // Indicates context menu available
                  }}
                >
                  {row.cells.map(cell => (
                    <td {...cell.getCellProps()} style={{ padding: '10px', borderBottom: '1px solid #ddd' }}>
                      {cell.render('Cell')}
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : <p>No results found</p>}

      {/* Custom context menu */}
      {contextMenu && contextMenu.visible && (
        <div
          style={{
            position: 'absolute',
            top: `${contextMenu.y}px`,
            left: `${contextMenu.x}px`,
            backgroundColor: 'white',
            boxShadow: '0px 0px 10px rgba(0,0,0,0.2)',
            borderRadius: '5px',
            overflow: 'hidden',
            zIndex: 1000,
          }}
        >
          <div
            onClick={() => fetchSimilarTracks(contextMenu.track)}
            style={{
              padding: '10px 20px',
              cursor: 'pointer',
              borderBottom: '1px solid #ddd',
              backgroundColor: '#f9f9f9',
              color: '#333',
            }}
          >
            Get Similar Tracks
          </div>
          <div
            onClick={() => setContextMenu(null)} // Close menu option
            style={{
              padding: '10px 20px',
              cursor: 'pointer',
              backgroundColor: '#f9f9f9',
              color: '#333',
            }}
          >
            Close
          </div>
        </div>
      )}
    </div>
  );
};

export default TrackSearch;
